import{_ as l,o as i,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2022-06-02","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-06-02","date":"2022-06-02T00:00:00.000Z","updated":"2022-06-03T00:00:00.000Z","tags":["Ceph","性能优化","代码审查","测试","Ford合作"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-06-02.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-06-02.md","lastUpdated":1780460162000}'),o={name:"posts/2022/Ceph_Performance_Meeting_2022-06-02.md"};function p(a,e,n,s,_,g){return i(),t("div",null,[...e[0]||(e[0]=[r('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>在2022年6月2日的Ceph性能会议上，与会者讨论了多个与Ceph存储系统相关的重要议题。以下是对会议主要内容的总结：</p><p><strong>会议主题</strong>：Ceph存储系统性能优化、代码审查、测试以及与Ford公司的合作。</p><p><strong>主要议题</strong>：</p><ol><li><p><strong>性能优化</strong>：</p><ul><li>针对Ceph文件系统性能进行了优化，特别是对处理小文件和大文件的不同策略。</li><li>探讨了无PG日志的经典OSD在调整分片数、线程数和信使线程数时的行为，以提升性能。</li><li>认识到在高竞争条件下，信使线程的效率显著下降，需要进一步研究。</li></ul></li><li><p><strong>代码审查</strong>：</p><ul><li>对statifik update PR进行了代码审查，并已通过。</li><li>对yanker tracing PR进行了讨论，并已批准。</li><li>讨论了buffer bloat缓解PR的审查，Sam需要审查此PR。</li><li>讨论了bt PR审查，由于旧输出目录数据导致问题，已进行清理。</li></ul></li><li><p><strong>测试</strong>：</p><ul><li>强调了测试新引入的RPC方法对性能的影响。</li><li>讨论了snap删除的性能，特别是删除大量快照时的开销。</li><li>讨论了如何优化快照删除的性能，包括修改snap删除代码中的限制。</li></ul></li><li><p><strong>与Ford公司的合作</strong>：</p><ul><li>与Ford公司的合作项目正在等待最终审批，一旦获批将开始实施。</li><li>讨论了Igor的新存储（Blue Store）进展，包括解决部署OSD时空间不足的问题。</li></ul></li><li><p><strong>其他议题</strong>：</p><ul><li>讨论了Ceph存储中的缓存行竞争和锁竞争问题。</li><li>讨论了将PG日志移至Cyclic Buffer的可能性，以减少对数据库的影响。</li><li>讨论了RBD镜像中的快照删除性能问题，以及如何通过优化迭代行为来提高性能。</li></ul></li></ol><p><strong>后续行动计划</strong>：</p><ul><li>继续优化Ceph文件系统性能，特别是针对小文件和大文件的处理。</li><li>完成代码审查，确保线程安全和内存泄漏问题得到解决。</li><li>重点关注新引入的RPC方法的性能影响。</li><li>推进与Ford公司的合作项目。</li><li>进一步研究快照删除的性能，包括迭代优化和数据库写入优化。</li></ul><p>会议安排：下一次会议将在下周同一时间举行。</p>',8)])])}const u=l(o,[["render",p]]);export{c as __pageData,u as default};
